import UserPage from 'flarum/forum/components/UserPage';
import ModeratorNotes from './ModeratorNotes';
export default class ModeratorNotesPage extends UserPage {
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  content() {
    return m("div", {
      className: "DiscussionsUserPage"
    }, m(ModeratorNotes, {
      user: this.user,
      sort: "sort"
    }));
  }
}
flarum.reg.add('fof-moderator-notes', 'forum/components/ModeratorNotesPage', ModeratorNotesPage);